package org.beckenburg.editor;

import java.io.*;
import java.nio.*;
import java.util.*;

/** Canonical face order survives per-part GLB node grouping and shared source instances. */
final class EditorMeshOrder {
    private EditorMeshOrder(){}
    static void attach(Map<String,Object> root,int node,List<Integer> order){var target=EditorGlbReader.obj(EditorGlbReader.arr(root.get("nodes")).get(node));var extensions=target.get("extensions") instanceof Map<?,?> existing?new LinkedHashMap<>(EditorGlbReader.obj(existing)):new LinkedHashMap<String,Object>();extensions.put("BECK_native_order",Map.of("version",1,"triangles",List.copyOf(order)));target.put("extensions",extensions);var used=root.get("extensionsUsed") instanceof List<?> existing?new ArrayList<Object>(existing):new ArrayList<Object>();if(!used.contains("BECK_native_order"))used.add("BECK_native_order");root.put("extensionsUsed",used);}
    private static int integer(Object value)throws IOException{if(!(value instanceof Number number))throw new IOException("Invalid native GLB face order value");try{return new java.math.BigDecimal(number.toString()).intValueExact();}catch(ArithmeticException invalid){throw new IOException("Invalid native GLB face order value",invalid);}}
    static List<EditorGlbReader.Face> read(Map<String,Object> root,List<EditorGlbReader.Primitive> primitives)throws IOException{
        var groups=new LinkedHashMap<Integer,List<EditorGlbReader.Primitive>>();int total=0;for(var p:primitives){groups.computeIfAbsent(p.node(),key->new ArrayList<>()).add(p);total+=p.indices().size()/3;}var orders=new HashMap<Integer,List<Integer>>();var nodes=EditorGlbReader.arr(root.get("nodes"));
        for(var group:groups.entrySet()){var node=EditorGlbReader.obj(nodes.get(group.getKey()));if(node.get("extensions") instanceof Map<?,?> extensions&&extensions.containsKey("BECK_native_order")){var metadata=EditorGlbReader.obj(extensions.get("BECK_native_order"));if(!metadata.keySet().equals(Set.of("version","triangles"))||integer(metadata.get("version"))!=1)throw new IOException("Unsupported native GLB face order");var encoded=EditorGlbReader.arr(metadata.get("triangles"));int count=group.getValue().stream().mapToInt(p->p.indices().size()/3).sum();if(encoded.size()!=count)throw new IOException("Native GLB face order count differs");var order=new ArrayList<Integer>();for(var value:encoded)order.add(integer(value));orders.put(group.getKey(),order);}}
        boolean[] seen=new boolean[total];var faces=new ArrayList<EditorGlbReader.Face>();int ordinal=0;for(var group:groups.entrySet()){var order=orders.get(group.getKey());if(!orders.isEmpty()&&order==null)throw new IOException("Incomplete native GLB face order");int local=0;for(var p:group.getValue())for(int t=0;t<p.indices().size()/3;t++){int id=order==null?ordinal:order.get(local++);if(id<0||id>=total||seen[id])throw new IOException("Invalid/duplicate native GLB face order");seen[id]=true;faces.add(new EditorGlbReader.Face(p,t,id));ordinal++;}}
        faces.sort(Comparator.comparingLong(EditorGlbReader.Face::identity));return List.copyOf(faces);
    }
    static String key(int node,int primitive,int triangle){return node+":"+primitive+":"+triangle;}
    static void source(Map<String,Object> root,byte[] binary,EditorMeshPipeline.Mesh mesh,Map<String,Integer> parts)throws IOException{
        var original=new HashMap<String,Long>();for(var face:mesh.glbSource().faces())original.put(key(face.primitive().node(),face.primitive().primitive(),face.triangle()),face.identity());var draw=new HashMap<Long,Integer>();for(int i=0;i<mesh.faceIds().size();i++)draw.put(mesh.faceIds().get(i),i);int firstNewAccessor=EditorGlbReader.arr(mesh.glbSource().root().get("accessors")).size();var nodes=EditorGlbReader.arr(root.get("nodes"));var meshes=EditorGlbReader.arr(root.get("meshes"));var accessors=EditorGlbReader.arr(root.get("accessors"));var views=EditorGlbReader.arr(root.get("bufferViews"));var bytes=ByteBuffer.wrap(binary).order(ByteOrder.LITTLE_ENDIAN);
        for(int node:new LinkedHashSet<>(parts.values())){var object=EditorGlbReader.obj(nodes.get(node));if(!object.containsKey("mesh"))continue;var primitives=EditorGlbReader.arr(EditorGlbReader.obj(meshes.get(integer(object.get("mesh")))).get("primitives"));var order=new ArrayList<Integer>();for(int pi=0;pi<primitives.size();pi++){var p=EditorGlbReader.obj(primitives.get(pi));int count=integer(EditorGlbReader.obj(accessors.get(integer(p.get("indices")))).get("count"))/3;boolean generated=integer(EditorGlbReader.obj(p.get("attributes")).get("POSITION"))>=firstNewAccessor;var ids=generated?EditorGlbReader.identities(p,"beckenburgFaceIds",count,bytes,0,binary.length,views):List.<Long>of();for(int tri=0;tri<count;tri++){Long nativeId=generated?ids.get(tri):original.get(key(node,pi,tri));Integer index=draw.get(nativeId);if(index==null)throw new IOException("Native face order lost its actual authoring face");order.add(index);}}attach(root,node,order);}
    }
}
